Import ListNotations.
Open Scope Z_scope.
Set Warnings "-notation-for-abbreviation".
Local Ltac Z.euclidean_division_equations_cleanup ::= idtac.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.

Section LV2.
  Variables (sp gp tp : word) (F : bvmap 5 word) (fc : bv 32).
  Variables (x1 x11 x13 x27 : word).
  Variables (m : fmem) (DT SY WK cons T nbb wEnd start sym1 minW : Z) (sorted : list (option Z)) (js jt : list byte)
    (ncells : nat) (rs0 rv : list Z).
  Variable POST : machine_state -> Prop.
  Hypothesis HJT : length jt = (4 * ncells)%nat.
  Hypothesis HJS : length js = length sorted.
  Hypothesis HLS : length sorted = 256%nat.
  Hypothesis HSYR : forall i v, nth i sorted None = Some v -> 0 <= v < 256.
  Hypothesis HDT : 0 < DT /\ DT + 4 + 4 * Z.of_nat ncells <= 2^47.
  Hypothesis HSYE : SY = WK + 736.
  Hypothesis HWK : 0 < WK /\ WK + 2124 <= 2^47.
  Hypothesis DJ : DT + 4 + 4 * Z.of_nat ncells <= WK \/ WK + 2124 <= DT + 4.
  Hypothesis HS1 : 0 <= sym1 < 256.
  Hypothesis HT : 1 <= T <= 12.
  Hypothesis HNBB : 2 <= nbb <= 13.
  Hypothesis HWE : 2 <= wEnd <= nbb.
  Hypothesis HCONS : 1 <= cons <= 11.
  Hypothesis HMW : 1 <= minW /\ cons + nbb - T <= minW.
  Hypothesis HST : 0 <= start.
  Hypothesis LRS : length rs0 = 15%nat.
  Hypothesis HRSV : forall w, 1 <= w <= wEnd - 1 -> 0 <= Znth w rs0 <= Znth (w + 1) rs0 /\ Znth (w + 1) rs0 <= 256.
  Hypothesis LRV : length rv = 156%nat.
  Variable PRV : Z -> Prop.
  Hypothesis HPRV : forall w, minW <= w <= wEnd - 1 -> PRV (rv_idx cons w).
  Hypothesis HRVR : forall w, minW <= w <= wEnd - 1 -> 0 <= Znth (rv_idx cons w) rv < 2^32.
  Hypothesis RSA0 : u32arr psegs m (WK + 676) (map (Z_to_bv 64) rs0).
  Hypothesis RVA0 : rv_at m WK rv PRV.
  Notation INV m1 dt := (x2f_inv m m1 DT SY js jt sorted ncells dt).

  Lemma lv2_loop : forall f w2 dt m1 r (x5 x8 x9 x10 x14 x17 x21 x25 x26 x28 : word),
    level2_weights f dt start w2 wEnd T cons rv sorted rs0 nbb sym1 = Ok r ->
    wEnd - w2 < Z.of_nat f -> minW <= w2 < wEnd -> INV m1 dt ->
    (forall m2 dt' (y5 y8 y9 y10 y14 y17 y21 y25 y26 y28 : word),
       r = dt' -> INV m2 dt' ->
       evt psegs POST (MS (mkR x1 sp gp tp y5 (Z_to_bv 64 wEnd) (Z_to_bv 64 (WK + 52 * cons)) y8 y9 y10 x11
                               (Z_to_bv 64 (Z.lor sym1 33554432)) x13 y14 (Z_to_bv 64 (WK + 676)) (Z_to_bv 64 (cons + nbb))
                               y17 (Z_to_bv 64 2) (Z_to_bv 64 4) (Z_to_bv 64 8) y21 (Z_to_bv 64 wEnd) (Z_to_bv 64 T)
                               (Z_to_bv 64 SY) y25 y26 x27 y28 (Z_to_bv 64 (DT + 4 + 4 * start)) (Z_to_bv 64 1)
                               (Z_to_bv 64 3))
                          F (Z_to_bv 64 0x13fa4) fc None m2 (seg_rom psegs))) ->
    evt psegs POST (MS (mkR x1 sp gp tp x5 (Z_to_bv 64 wEnd) (Z_to_bv 64 (WK + 52 * cons)) x8 x9 x10 x11
                            (Z_to_bv 64 (Z.lor sym1 33554432)) x13 x14 (Z_to_bv 64 (WK + 676)) (Z_to_bv 64 (cons + nbb))
                            x17 (Z_to_bv 64 2) (Z_to_bv 64 4) (Z_to_bv 64 8) x21 (Z_to_bv 64 w2) (Z_to_bv 64 T)
                            (Z_to_bv 64 SY) x25 x26 x27 x28 (Z_to_bv 64 (DT + 4 + 4 * start)) (Z_to_bv 64 1)
                            (Z_to_bv 64 3))
                       F (Z_to_bv 64 0x140c8) fc None m1 (seg_rom psegs)).
